using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Diagnostics;using System.Collections.Generic;using System.Threading.Tasks;
sealed partial class WorkspaceWindow {
 readonly Dictionary<string,string> studioChoices=new Dictionary<string,string>();
 string ChoicesFile {get{return Path.Combine(root,"studio-locations.json");}}
 string StudioDirectory(string key){return key=="music"?"Music-SFX":key=="library"?"Library-Production":char.ToUpper(key[0])+key.Substring(1);}
 string[] StudioNames(string key){string label=key=="music"?"Sound":key=="library"?"Library":key=="worldbuilding"?"World":StudioDirectory(key);return new[]{"Jago-"+label+".exe","Jago-"+StudioDirectory(key)+"-Studio.exe"};}
 string BundledExe(string key){foreach(string location in new[]{bundle,Path.Combine(bundle,"Studios"),@"C:\Jago Studio Dev\Studios"})foreach(string name in StudioNames(key)){string path=Path.Combine(location,StudioDirectory(key),name);if(File.Exists(path))return path;}return null;}
 void LoadStudioChoices(){studioChoices.Clear();if(!File.Exists(ChoicesFile))return;try{var saved=json.Deserialize<Dictionary<string,string>>(ReadShared(ChoicesFile));if(saved!=null)foreach(var entry in saved)if(studios.ContainsKey(entry.Key)&&!String.IsNullOrWhiteSpace(entry.Value)&&Path.IsPathRooted(entry.Value))studioChoices[entry.Key]=entry.Value;}catch{SetStatus("Studio choices could not be read. Choose releases again in Manage studios.");}}
 void SaveStudioChoices(){Atomic(ChoicesFile,json.Serialize(studioChoices));}
 void ValidateStudio(string key,string path){if(!File.Exists(path))throw new FileNotFoundException("This release is no longer at that location.",path);if(!StudioNames(key).Contains(Path.GetFileName(path),StringComparer.OrdinalIgnoreCase))throw new InvalidOperationException("Choose the Jago "+studios[key]+" executable, not another studio or an HTML file.");var version=FileVersionInfo.GetVersionInfo(path);if(String.IsNullOrWhiteSpace(version.ProductName)||!version.ProductName.StartsWith("Jago",StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("This file does not identify itself as a Jago studio.");}
 void ChooseStudio(string key,string path){path=Path.GetFullPath(path);ValidateStudio(key,path);studioChoices[key]=path;SaveStudioChoices();}
 string StudioVersion(string path){if(path==null||!File.Exists(path))return "Unavailable";try{var info=FileVersionInfo.GetVersionInfo(path);return info.FileVersion??info.ProductVersion??"Version not supplied";}catch{return "Version unavailable";}}
 string StudioDetails(string key){string selected;bool custom=studioChoices.TryGetValue(key,out selected);string path=custom?selected:BundledExe(key);string running=String.Join(", ",items.Concat(detachedItems).Where(t=>t.studio==key&&t.process!=null&&!t.process.HasExited).Select(t=>{try{return StudioVersion(t.process.MainModule.FileName);}catch{return "open";}}).Distinct());string state=custom?"Chosen release":"Bundle / local development copy";string extra="";if(key=="library"&&path!=null&&File.Exists(path)){string folder=Path.GetDirectoryName(path);if(!File.Exists(Path.Combine(folder,"Tools","PDF","Jago-PDF-Engine.exe"))||!File.Exists(Path.Combine(folder,"Tools","OCR","tesseract.min.js")))extra="\nOffline PDF conversion / OCR files are not present beside this copy.";}return state+"  ·  "+StudioVersion(path)+"\n"+(path??"No studio found. Choose an extracted release.")+(running.Length>0?"\nOpen tabs: "+running+". Close and reopen them to use a different release.":"")+extra;}
 void ManageStudios(string focus=null){using(var form=new Form{Text="Manage Jago studios",Size=new Size(980,850),MinimumSize=new Size(750,560),StartPosition=FormStartPosition.CenterParent,Font=Font,BackColor=BackColor,ForeColor=ForeColor,ShowInTaskbar=false}){
 var body=new Panel{Dock=DockStyle.Fill,Padding=new Padding(24)};var title=new Label{Text="Your studios, your versions",Dock=DockStyle.Top,Height=45,Font=new Font(Font.FontFamily,21,FontStyle.Bold)};
 var help=new Label{Text="Choose the .exe in an extracted release. Keep its supporting files beside it. Workscape remembers your choice; open tabs keep their running version. You can also drop a studio .exe onto its card.",Dock=DockStyle.Top,Height=65};
 var list=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true,FlowDirection=FlowDirection.TopDown,WrapContents=false};
 Action refresh=null;var labels=new Dictionary<string,Label>();refresh=()=>{foreach(var entry in labels)entry.Value.Text=StudioDetails(entry.Key);};
 foreach(var studio in studios){string key=studio.Key;var card=new Panel{Width=875,Height=150,Margin=new Padding(0,0,0,12),Padding=new Padding(12),BackColor=ControlPaint.Light(BackColor,.08f),AllowDrop=true};var heading=new Label{Text="Jago "+studio.Value,Dock=DockStyle.Top,Height=27,Font=new Font(Font.FontFamily,13,FontStyle.Bold)};var details=new Label{Dock=DockStyle.Fill,AutoEllipsis=true};labels[key]=details;
 var actions=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=38,WrapContents=false};Func<string,Button> action=text=>new Button{Text=text,AutoSize=true,Height=32,FlatStyle=FlatStyle.Flat,BackColor=BackColor,ForeColor=ForeColor,Margin=new Padding(0,0,8,0)};
 Action<string> select=path=>{try{ChooseStudio(key,path);refresh();SetStatus("New Jago "+studio.Value+" tabs will use "+StudioVersion(path)+".");}catch(Exception e){details.Text=e.Message+"\n"+StudioDetails(key);}};
 var choose=action("Choose release…");choose.Click+=(a,b)=>{using(var picker=new OpenFileDialog{Title="Choose Jago "+studio.Value+" from an extracted release",Filter="Jago studio executable|*.exe",CheckFileExists=true,Multiselect=false,RestoreDirectory=true}){string current;studioChoices.TryGetValue(key,out current);if(current==null)current=BundledExe(key);if(current!=null&&Directory.Exists(Path.GetDirectoryName(current)))picker.InitialDirectory=Path.GetDirectoryName(current);if(picker.ShowDialog(form)==DialogResult.OK)select(picker.FileName);}};
 var reset=action("Use bundled copy");reset.Click+=(a,b)=>{studioChoices.Remove(key);SaveStudioChoices();refresh();};var reveal=action("Show folder");reveal.Click+=(a,b)=>{try{string current;studioChoices.TryGetValue(key,out current);current=current??BundledExe(key);if(current!=null&&Directory.Exists(Path.GetDirectoryName(current)))Process.Start(new ProcessStartInfo("explorer.exe","/select,\""+current+"\""){UseShellExecute=true});else details.Text="That folder has moved. Choose the release again.\n"+StudioDetails(key);}catch(Exception e){details.Text=e.Message;}};
 actions.Controls.Add(choose);actions.Controls.Add(reset);actions.Controls.Add(reveal);card.Controls.Add(details);card.Controls.Add(heading);card.Controls.Add(actions);card.DragEnter+=(a,b)=>{if(b.Data.GetDataPresent(DataFormats.FileDrop)&&((string[])b.Data.GetData(DataFormats.FileDrop)).Length==1)b.Effect=DragDropEffects.Link;};card.DragDrop+=(a,b)=>{var paths=b.Data.GetData(DataFormats.FileDrop) as string[];if(paths!=null&&paths.Length==1)select(paths[0]);};list.Controls.Add(card);if(key==focus)form.Shown+=(a,b)=>list.ScrollControlIntoView(card);}
 list.Resize+=(a,b)=>{foreach(Control card in list.Controls)card.Width=Math.Max(650,list.ClientSize.Width-25);};refresh();var close=new Button{Text="Done",Dock=DockStyle.Bottom,Height=44,FlatStyle=FlatStyle.Flat,BackColor=BackColor,ForeColor=ForeColor};close.Click+=(a,b)=>form.Close();body.Controls.Add(list);body.Controls.Add(help);body.Controls.Add(title);form.Controls.Add(body);form.Controls.Add(close);form.CancelButton=close;
 if(WorkspaceProgram.Test!=null){var capture=new System.Windows.Forms.Timer{Interval=500};capture.Tick+=(a,b)=>{capture.Stop();using(var image=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(image,new Rectangle(0,0,form.Width,form.Height));image.Save(Path.Combine(WorkspaceProgram.Test,"studio-manager.png"));}form.Close();capture.Dispose();};capture.Start();}form.ShowDialog(this);
 }}
 async Task StudioManagerTest(){var checks=new List<string>();Action<string,bool> check=(label,ok)=>{if(!ok)throw new Exception(label);checks.Add(label);};try{string release=File.Exists(Path.Combine(root,"chosen-studio.txt"))?ReadShared(Path.Combine(root,"chosen-studio.txt")).Trim():Path.Combine(@"C:\Jago Studio Dev\Releases\Library-Production\Current\Library-0.8.0","Jago-Library.exe");string original=BundledExe("library");check("Bundled studio fallback is available",original!=null);ChooseStudio("library",release);check("Chosen release overrides bundled copy",Exe("library")==release);LoadStudioChoices();check("Chosen release survives reloading preferences",Exe("library")==release);check("Selected release version is shown",StudioDetails("library").Contains(StudioVersion(release)));bool rejected=false;try{ChooseStudio("wobble",release);}catch{rejected=true;}check("Wrong studio executable is rejected",rejected);check("Rejected selection does not replace preferences",!studioChoices.ContainsKey("wobble"));studioChoices["library"]=Path.Combine(root,"missing","Jago-Library.exe");rejected=false;try{Exe("library");}catch(FileNotFoundException){rejected=true;}check("Missing custom release does not silently open an older copy",rejected);ChooseStudio("library",release);ManageStudios("library");var tab=Add("library");for(int i=0;i<300&&!tab.attached;i++){await Tick();await Task.Delay(100);}check("Selected standalone release embeds in Workscape",tab.attached);check("Actual child process uses the selected release",String.Equals(tab.process.MainModule.FileName,release,StringComparison.OrdinalIgnoreCase));await CaptureTab(tab);check("Selected release captures an editable document",File.Exists(Path.Combine(tab.folder,"snapshot.json")));if(File.Exists(Path.Combine(root,"chosen-studio.txt"))){await ProbeChild(tab,"(async()=>{try{const {writer}=await pdfReady(),doc=await writer.PDFDocument.create();doc.addPage().drawText('Workscape invoice search');const bytes=await doc.save();await openPDFReader({id:'embedded-search',name:'Embedded PDF typing',type:'pdf',url:'data:application/pdf;base64,'+bytesBase64(bytes),size:bytes.length});const input=$('pdfReaderSearch');input.focus();await new Promise(resolve=>{chrome.webview.addEventListener('message',function h(e){if(e.data.type==='jago-test-typed'){chrome.webview.removeEventListener('message',h);resolve();}});chrome.webview.postMessage({type:'jago-test-type',text:'invoice'});});await new Promise(r=>setTimeout(r,800));if(input.value!=='invoice'||document.activeElement!==input||!$('pdfFindCount').textContent.includes('1 matching'))throw Error('Embedded search input failed');window.__workspaceTestResult={ok:true};}catch(e){window.__workspaceTestResult={error:e.message};}})()");check("PDF typing and search work inside Workscape",true);Command(tab,"test-preview",new Dictionary<string,object>{{"name","embedded-pdf-search.png"}});await Task.Delay(500);}studioChoices.Remove("library");SaveStudioChoices();check("Return to bundled restores default resolution",Exe("library")==original);check("Changing selection leaves the running document intact",!tab.process.HasExited&&String.Equals(tab.process.MainModule.FileName,release,StringComparison.OrdinalIgnoreCase));await CloseChild(tab);Atomic(Path.Combine(root,"result.json"),json.Serialize(new{ok=true,checks=checks}));}catch(Exception e){Atomic(Path.Combine(root,"result.json"),json.Serialize(new{ok=false,error=e.ToString(),checks=checks}));foreach(var tab in items)Command(tab,"close");}allowClose=true;Close();}
}

